✔ Tilauksen tilan ja historian tarkastelu','VAT number field visibilityHidden' => 'Piilotettu','VAT number field visibilityOptional' => 'Valinnainen','VAT number field visibilityRequired' => 'Pakollinen','Delivery typeShipping to address' => 'Toimitusosoite','Delivery typeLocal pickup' => 'Nouto paikan päältä',] ];